"""
Goal of this file is to convert every audio file into a log mel-spectrogram for the CNN
"""

import os
import glob

import numpy as np
import librosa


# Function generated by claude code, model Opus 5.5
# Prompt: Do the spectogram creation code here, remember it will be called in final_data.py
def create_spectrograms(audio_path, out_path, sr=22050, n_mels=128, n_fft=2048,
                        hop_length=512, clip_seconds=30.0):
    """
    Convert every mp3 under audio_path/<folder>/<track>.mp3 into a log mel-spectrogram
    and save it as out_path/<track_id>.npy.

    Every clip is padded/trimmed to clip_seconds so all spectrograms have the same
    shape: (n_mels, 1 + int(sr * clip_seconds) // hop_length) -> (128, 1292) by default.

    Tracks that already have a .npy in out_path are skipped, so re-running is fast.
    Returns the number of spectrograms created.
    """
    os.makedirs(out_path, exist_ok=True)
    paths = sorted(glob.glob(os.path.join(audio_path, "*", "*.mp3")))
    n_samples = int(sr * clip_seconds)
    created = 0

    for path in paths:
        track_id = int(os.path.splitext(os.path.basename(path))[0])
        out_file = os.path.join(out_path, f"{track_id}.npy")

        if os.path.exists(out_file):
            continue

        # Load at a fixed sample rate, then pad/trim so every clip is the same length
        y, _ = librosa.load(path, sr=sr, duration=clip_seconds)
        y = librosa.util.fix_length(y, size=n_samples)

        mel = librosa.feature.melspectrogram(y=y, sr=sr, n_fft=n_fft,
                                             hop_length=hop_length, n_mels=n_mels)
        log_mel = librosa.power_to_db(mel, ref=np.max).astype(np.float16)

        np.save(out_file, log_mel)
        created += 1

    print(f"Created {created} spectrograms, {len(paths) - created} already existed")
    return created
